describe('External Links Navigation', () => {
    beforeEach(() => {
        cy.visit('https://example.com'); // Replace with the actual URL of the application
    });

    it('should open external links in a new tab', () => {
        cy.get('a.external-link') // Replace with the actual selector for external links
            .should('have.attr', 'target', '_blank')
            .and('have.attr', 'rel', 'noopener noreferrer');
    });

    it('should not navigate to the external link in the same tab', () => {
        cy.get('a.external-link') // Replace with the actual selector for external links
            .invoke('removeAttr', 'target') // Temporarily remove target to test navigation
            .click();

        cy.url().should('not.eq', 'https://external-link.com'); // Replace with the actual external link
    });
});
